/* VmRSS: memoria física que el proceso tiene ocupada ahora (lo lee de /proc/self/status) */
static long rss_kib(void) {
    FILE *f = fopen("/proc/self/status", "r");
    char linea[256]; long kib = -1;
    while (f && fgets(linea, sizeof linea, f))
        if (sscanf(linea, "VmRSS: %ld kB", &kib) == 1) break;
    if (f) fclose(f);
    return kib;
}

static void procesar_pedido(int n) {
    char *buffer = malloc(1 << 20);      /* pide 1 MiB al montículo */
    memset(buffer, n, 1 << 20);          /* lo usa (si no lo toca, el sistema ni lo asigna) */
    /* ...usa el buffer... y se olvida de llamar a free(buffer) */
}

int main(void) {
    printf("al empezar: %ld KiB\n", rss_kib());
