// Un montículo de juguete: cada objeto sabe a quiénes apunta
const monticulo = new Map();
const nuevo = (nombre, apunta = []) => monticulo.set(nombre, { apunta, marca: false });

nuevo("app", ["inicio", "oyentes"]);        // objetos vivos
nuevo("inicio", ["lecciones"]);
nuevo("lecciones");
nuevo("oyentes", ["pantallaVieja"]);        // un oyente olvidado todavía apunta a una pantalla cerrada
nuevo("pantallaVieja", ["datosPesados"]);
nuevo("datosPesados");
nuevo("borrador1", ["borrador2"]);          // un ciclo que nadie más mira
nuevo("borrador2", ["borrador1"]);
nuevo("huerfano");                          // nadie lo menciona

const raices = ["app"];                      // lo que el programa tiene a mano: pila y variables globales

function marcar(nombre) {                    // fase 1: recorrer lo alcanzable desde las raíces
  const o = monticulo.get(nombre);
  if (!o || o.marca) return;
  o.marca = true;
  o.apunta.forEach(marcar);
}

function barrer() {                          // fase 2: liberar lo que no quedó marcado
  const liberados = [];
  for (const [nombre, o] of monticulo) {
    if (o.marca) o.marca = false;            // se desmarca para la próxima vuelta
    else { monticulo.delete(nombre); liberados.push(nombre); }
  }
  return liberados;
}

function recolectar() {
  raices.forEach(marcar);
  return barrer();
}

console.log("antes:  ", [...monticulo.keys()].join(", "));
console.log("liberó: ", recolectar().join(", "));
