impl Drop for Pedido {
    fn drop(&mut self) {
        println!("  se libera el pedido de {}", self.cliente);
    }
}

fn despachar(p: Pedido) {
    println!("  despachando a {}", p.cliente);
}   // acá termina la función: p sale de alcance y se libera

