// Se ejecuta con: node --expose-gc cache.js
const MB = () => { global.gc(); return (process.memoryUsage().heapUsed / 1048576).toFixed(1); };

function probar(nombre, tope) {
  const cache = new Map();
  console.log(nombre);
  for (let id = 1; id <= 40000; id++) {
    cache.set(id, new Array(500).fill(id));        // respuesta guardada «por si se repite»
    if (tope && cache.size > tope) cache.delete(cache.keys().next().value);   // saca la más vieja
    if (id % 10000 === 0) console.log(`  tras ${id} pedidos: ${MB()} MB en uso, ${cache.size} entradas`);
  }
}
probar("caché sin tope", 0);
global.gc();
probar("caché con tope de 1000", 1000);

const { EventEmitter } = require("node:events");
const MB = () => { global.gc(); return (process.memoryUsage().heapUsed / 1048576).toFixed(1); };

const teclado = new EventEmitter();     // vive toda la vida de la app
teclado.setMaxListeners(0);             // callamos el aviso de Node para medir

function abrirPantalla(id, limpiar) {
  const datosPesados = new Array(50000).fill(id);        // lo que la pantalla necesita (~400 KB)
  const alCambiar = (alto) => datosPesados.length + alto; // el oyente «recuerda» datosPesados
  teclado.on("cambio", alCambiar);
  return limpiar ? () => teclado.off("cambio", alCambiar) : () => {};
}

console.log("sin limpiar:");
for (let i = 1; i <= 300; i++) {
  const cerrar = abrirPantalla(i, false);
  cerrar();                                   // la pantalla «se cierra», pero el oyente queda
  if (i % 100 === 0) console.log(`  ${i} pantallas abiertas y cerradas: ${MB()} MB, oyentes vivos: ${teclado.listenerCount("cambio")}`);
}
teclado.removeAllListeners("cambio");
console.log("después de limpiar todo:", MB(), "MB");

console.log("limpiando al cerrar:");
for (let i = 1; i <= 300; i++) {
  const cerrar = abrirPantalla(i, true);
  cerrar();
  if (i % 100 === 0) console.log(`  ${i} pantallas abiertas y cerradas: ${MB()} MB, oyentes vivos: ${teclado.listenerCount("cambio")}`);
}
